// === Tab: mySketch ===
let new_shader;
let NUM = 60;
let lapse = 0;    // mouse timer

function setup() {
	createCanvas(1112, 834, WEBGL);
	new_shader = createShader(vert, frag);
	noStroke();
}

function draw() {
	background(255);
	new_shader.setUniform("time", millis()/1000.0);
	shader(new_shader);
	for (let i=0; i<NUM; i++) {
		push();
		translate(300*cos(TWO_PI*i/NUM), 300*sin(TWO_PI*i/NUM), 0);
		rotateX(millis()/1000.0 + TWO_PI*i/NUM);
		rotateY(millis()/1000.0 + TWO_PI*i/NUM);
		box(400, 20);
		pop();
	}
}

function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 200){
    save('pix.jpg');
    lapse = millis();
  }
}

// === Tab: shader ===
let vert = `
attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec3 aNormal;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

varying vec3 vVertexNormal;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
	vVertexNormal = normalize(vec3(uNormalMatrix * aNormal));
}
`;


let frag = `
precision mediump float;

uniform vec4 uMaterialColor;
uniform float time;

varying vec3 vVertexNormal;

vec3 hsb2rgb( in vec3 c ){
    vec3 rgb = clamp(abs(mod(c.x * 6.0+vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void main(void) {
  gl_FragColor = vec4(hsb2rgb(normalize(vVertexNormal + 0.5 * sin(time) + 0.5)), 1.0);
}
`;

